SELECT id, name, salary, salary_min, salary_max, company, company_size, tags, location, education, experience, financing, create_time FROM job_position
AND (name LIKE CONCAT('%', #{keyword}, '%') OR company LIKE CONCAT('%', #{keyword}, '%') OR location LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%'))
AND location LIKE CONCAT(#{location}, '%')
AND education = #{education}
AND REPLACE(experience, ' ', '') = REPLACE(#{experience}, ' ', '')
AND REPLACE(company_size, ' ', '') = REPLACE(#{size}, ' ', '')
AND financing = #{financing}
AND salary_max >= #{salaryMin}
AND salary_min <= #{salaryMax}
ORDER BY id ASC
